// Client: SSE with native reconnect + snapshot-on-reconnect baseline
function connectFeed(topicId, onEvent) {
  let lastSeq = loadSeq(topicId);              // persisted per topic

  // 1) Baseline: refetch current snapshot after any (re)connect
  const snap = await fetch(`/api/topics/${topicId}/snapshot`).then((r) => r.json());
  onEvent({ type: 'snapshot', data: snap });
  lastSeq = snap.seq;

  const es = new EventSource(`/api/topics/${topicId}/stream?since=${lastSeq}`);
  es.onmessage = (e) => {
    const msg = JSON.parse(e.data);
    if (msg.seq <= lastSeq) return;            // dedupe replayed events
    lastSeq = msg.seq;
    saveSeq(topicId, lastSeq);
    onEvent(msg);
  };
  es.onerror = () => setStatus('reconnecting'); // EventSource retries natively
  es.onopen = () => setStatus('live');
  return es;                                    // .close() on unmount
}

// Server side (fan-out topology):
// BusinessService --domain event--> Redis pub/sub --> Realtime nodes --> SSE/WS clients
// Heartbeat every 30s; authorize topic subscription on connect;
// keep per-topic ring buffer (last ~1000 seqs) for `since` replay.

